/// <summary>
/// DP class for TO MultimodalDangerousGoods
/// </summary>
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
public class METMultimodalDangerousGoodsDP extends SrsReportDataProviderPreProcessTempDB
{
    METMultimodalDangerousGoodsTmp metMultimodalDangerousGoodsTmp;
    METMultimodalDangerousGoodsLineTmp metMultimodalDangerousGoodsLineTmp;
    RecordInsertList    headerList, lineList;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Get data from METMultimodalDangerousGoodsTmp
/// </summary>
/// <returns>METMultimodalDangerousGoodsTmp</returns>
[SrsReportDataSetAttribute(tableStr(METMultimodalDangerousGoodsTmp))]
public METMultimodalDangerousGoodsTmp getMETMultimodalDangerousGoodsTmp()
{
    select metMultimodalDangerousGoodsTmp;
    return metMultimodalDangerousGoodsTmp;
}

/// <summary>
/// Get data from METMultimodalDangerousGoodsLineTmp
/// </summary>
/// <returns>METMultimodalDangerousGoodsLineTmp</returns>
[SrsReportDataSetAttribute(tableStr(METMultimodalDangerousGoodsLineTmp))]
public METMultimodalDangerousGoodsLineTmp getMETMultimodalDangerousGoodsLineTmp()
{
    select metMultimodalDangerousGoodsLineTmp;
    return metMultimodalDangerousGoodsLineTmp;
}

/// <summary>
/// Report business logic
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    InventTable                         inventTable;
    METCommonReportContract             contract = this.parmDataContract();
    METCustTable metCustTable;
    InventLocation inventLocationTo;
    METInventLocation metInventLocationTo;

    headerList = new RecordInsertList(tableNum(METMultimodalDangerousGoodsTmp), true, true, true, true, true, metMultimodalDangerousGoodsTmp);
    lineList = new RecordInsertList(tableNum(METMultimodalDangerousGoodsLineTmp), true, true, true, true, true, metMultimodalDangerousGoodsLineTmp);

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId();

    select firstonly CustomerType from metCustTable
        exists join metInventLocationTo
        where metCustTable.AccountNum == metInventLocationTo.InternalCustomer
        exists join inventLocationTo
        where inventLocationTo.RecId == metInventLocationTo.InventLocation
        && inventLocationTo.InventLocationId == metSalesOrderShipmentLoadHeader.ToWarehouse;

    if(metCustTable.CustomerType != "Export")
    {
        return;
    }

    if (metSalesOrderShipmentLoadHeader)
    {
        this.insertHeaderData(metSalesOrderShipmentLoadHeader);

        headerList.insertDatabase();
    }


    while select  ItemId, Quantity, RecId from metSalesOrderShipmentLoadLines
            where  metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join inventTable
            where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId
                && inventTable.HMIMIndicator == NoYes::Yes
    {
        this.insertLineData(metSalesOrderShipmentLoadLines);
    }
    lineList.insertDatabase();
}

/// <summary>
/// Insert into Line table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
public void insertLineData(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines)
{
    InventTable inventTable;
    HMIMItemMaterial hmimItemMaterial;
    InventTransferLine inventTransferLine;
    InventItemSalesSetup inventItemSalesSetup;
    InventDim inventDim;
    const str x = "X";

    metMultimodalDangerousGoodsLineTmp.Qty = _metSalesOrderShipmentLoadLines.Quantity;


    select firstonly inventTable
        where inventTable.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metMultimodalDangerousGoodsLineTmp.ItemDescription = inventTable.itemName();
    metMultimodalDangerousGoodsLineTmp.GrossMass = (inventTable.NetWeight + inventTable.TaraWeight) * _metSalesOrderShipmentLoadLines.Quantity;
    metMultimodalDangerousGoodsLineTmp.NetMass = inventTable.NetWeight * _metSalesOrderShipmentLoadLines.Quantity;
    metMultimodalDangerousGoodsLineTmp.Cube = inventTable.UnitVolume * _metSalesOrderShipmentLoadLines.Quantity;
    metMultimodalDangerousGoodsLineTmp.ShipmentLoadLinesRecId = _metSalesOrderShipmentLoadLines.RecId;

    select firstonly UnitOfMeasure, TechnicalNameCode, DivisionCode, PackingGroupCode, Flashpoint, EMSCode, Qty
        from hmimItemMaterial
        where hmimItemMaterial.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metMultimodalDangerousGoodsLineTmp.UN = hmimItemMaterial.UnitOfMeasure;
    metMultimodalDangerousGoodsLineTmp.TechnicalNameCode = hmimItemMaterial.TechnicalNameCode;
    metMultimodalDangerousGoodsLineTmp.DivisionCode = hmimItemMaterial.DivisionCode;
    metMultimodalDangerousGoodsLineTmp.PackingGroupCode = hmimItemMaterial.PackingGroupCode;
    metMultimodalDangerousGoodsLineTmp.Flashpoint = hmimItemMaterial.Flashpoint;
    metMultimodalDangerousGoodsLineTmp.EMSCode = hmimItemMaterial.EMSCode;

    metMultimodalDangerousGoodsLineTmp.MultimodalHeaderGuidStr = headerReportGuid;
    metMultimodalDangerousGoodsLineTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;

    select firstonly UnitId, InventDimId from inventTransferLine
        where inventTransferLine.TransferId == _metSalesOrderShipmentLoadLines.OrderNum
        && inventTransferLine.LineNum == _metSalesOrderShipmentLoadLines.LineNum;

    metMultimodalDangerousGoodsLineTmp.KindOfPackage = inventTransferLine.UnitId;

    select firstonly METSalesUnit from inventItemSalesSetup
        exists join inventDim
        where inventItemSalesSetup.InventDimId == inventDim.inventDimId
        && inventItemSalesSetup.ItemId == _metSalesOrderShipmentLoadLines.ItemId
        && inventDim.InventSiteId == InventDim::find(inventTransferLine.InventDimId).InventSiteId;


    metMultimodalDangerousGoodsLineTmp.InnerPackaging = any2Str(hmimItemMaterial.Qty)+ x + hmimItemMaterial.UnitOfMeasure;
    metMultimodalDangerousGoodsLineTmp.OuterPackaging = any2Str(metMultimodalDangerousGoodsLineTmp.NetMass) + " " +inventItemSalesSetup.METSalesUnit;

    lineList.add(metMultimodalDangerousGoodsLineTmp);
}

/// <summary>
/// Insert into header table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertHeaderData(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    InventLocation inventLocationTo;
    METInventLocation metInventLocationTo;
    HMIMMultimodalDG hmimMultimodalDG;
    METHMIMMultimodalDG metHMIMMultimodalDG;

    select firstonly inventLocationTo 
        where inventLocationTo.InventLocationId == _metSalesOrderShipmentLoadHeader.ToWarehouse;

    metMultimodalDangerousGoodsTmp.IndustryKey = inventLocationTo.METWHSubEntity;
    metMultimodalDangerousGoodsTmp.WHName = inventLocationTo.Name;
    metMultimodalDangerousGoodsTmp.WHAddress = inventLocationTo.address();

    select firstonly metHMIMMultimodalDG
        where metHMIMMultimodalDG.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId;

    metMultimodalDangerousGoodsTmp.TransportDocumentNumber = metHMIMMultimodalDG.MMDGDocumentId;

    metMultimodalDangerousGoodsTmp.ShipmentId = _metSalesOrderShipmentLoadHeader.ShipmentId;

    select firstonly metInventLocationTo
        where metInventLocationTo.InventLocation == inventLocationTo.RecId;

    metMultimodalDangerousGoodsTmp.ConsigneeName = LogisticsLocation::find(CustTable::find(metInventLocationTo.InternalCustomer).postalAddress().Location).Description;
    metMultimodalDangerousGoodsTmp.ConsigneeAddress = CustTable::find(metInventLocationTo.InternalCustomer).postalAddress().Address;

    metMultimodalDangerousGoodsTmp.FreightForwarderReference = metHMIMMultimodalDG.FreightForwarderReference;
    metMultimodalDangerousGoodsTmp.CarrierCode = metHMIMMultimodalDG.CarrierCode;
    metMultimodalDangerousGoodsTmp.LoadingPort = metHMIMMultimodalDG.LoadingPort;
    metMultimodalDangerousGoodsTmp.DischargePort = metHMIMMultimodalDG.DischargePort;
    metMultimodalDangerousGoodsTmp.Destination = metHMIMMultimodalDG.Destination;

    metMultimodalDangerousGoodsTmp.ShipmentLoadHeaderRecId = _metSalesOrderShipmentLoadHeader.RecId;
    metMultimodalDangerousGoodsTmp.ContainerIdentificationNumber = metHMIMMultimodalDG.ContainerIdentificationNumber;
    metMultimodalDangerousGoodsTmp.NoAndKindOfPackage = metHMIMMultimodalDG.SealNum;
    metMultimodalDangerousGoodsTmp.ContainerInfo = metHMIMMultimodalDG.ContainerInfo;
    metMultimodalDangerousGoodsTmp.TareMass = metHMIMMultimodalDG.ContainerTareWeight;
    metMultimodalDangerousGoodsTmp.ShipperPreparation = metHMIMMultimodalDG.ShipperPreparation;

    metMultimodalDangerousGoodsTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    metMultimodalDangerousGoodsTmp.MultimodalHeaderGuidStr = headerReportGuid;
    headerList.add(metMultimodalDangerousGoodsTmp);
}
